USE MesaAyudaDb;
SET XACT_ABORT ON;
DECLARE @hash CHAR(64) = LOWER(CONVERT(VARCHAR(64), HASHBYTES('SHA2_256', 'Anthony123*'), 2));
EXEC dbo.sp_UsuarioAutenticar @Correo=N'anthony@mesaayuda.local', @PasswordHash=@hash;
BEGIN TRANSACTION;
DECLARE @u INT=(SELECT UsuarioId FROM dbo.Usuarios WHERE Correo=N'admin@mesaayuda.local');
DECLARE @d INT=(SELECT TOP 1 DepartamentoId FROM dbo.Departamentos);
DECLARE @c INT=(SELECT TOP 1 CategoriaId FROM dbo.Categorias);
DECLARE @p INT=(SELECT TOP 1 PrioridadId FROM dbo.Prioridades);
DECLARE @nuevo TABLE(TicketId INT, Numero VARCHAR(20), HashIntegridad CHAR(64));
INSERT @nuevo EXEC dbo.sp_TicketCrear @u,@d,@c,@p,N'Prueba de persona beneficiaria',N'  Ana López  ';
DECLARE @id INT=(SELECT TicketId FROM @nuevo);
IF NOT EXISTS (SELECT 1 FROM dbo.Tickets WHERE TicketId=@id AND PersonaBeneficiaria=N'Ana López' AND UsuarioSolicitanteId=@u AND HashIntegridad=dbo.fn_CalcularHashTicket(UsuarioSolicitanteId,DepartamentoId,CategoriaId,PrioridadId,Descripcion,FechaCreacion,EstadoId,TecnicoAsignadoId,PersonaBeneficiaria)) THROW 51000, 'Error guardando beneficiario o hash.', 1;
DECLARE @e INT=(SELECT EstadoId FROM dbo.Estados WHERE Nombre=N'En Proceso');
EXEC dbo.sp_TicketActualizar @TicketId=@id,@TecnicoId=NULL,@EstadoId=@e,@Nota=N'Prueba',@UsuarioAccionId=@u;
IF NOT EXISTS (SELECT 1 FROM dbo.Tickets WHERE TicketId=@id AND HashIntegridad=dbo.fn_CalcularHashTicket(UsuarioSolicitanteId,DepartamentoId,CategoriaId,PrioridadId,Descripcion,FechaCreacion,EstadoId,TecnicoAsignadoId,PersonaBeneficiaria)) THROW 51001, 'Error de hash al actualizar.', 1;
UPDATE dbo.Tickets SET PersonaBeneficiaria=N'Otra persona' WHERE TicketId=@id;
IF EXISTS (SELECT 1 FROM dbo.Tickets WHERE TicketId=@id AND HashIntegridad=dbo.fn_CalcularHashTicket(UsuarioSolicitanteId,DepartamentoId,CategoriaId,PrioridadId,Descripcion,FechaCreacion,EstadoId,TecnicoAsignadoId,PersonaBeneficiaria)) THROW 51002, 'No detecta alteracion.', 1;
ROLLBACK;
SELECT N'Creacion, actualizacion y deteccion de alteracion correctas. Prueba revertida.' AS Resultado;
SELECT COUNT(*) AS TicketsConHashInvalido FROM dbo.Tickets WHERE HashIntegridad<>dbo.fn_CalcularHashTicket(UsuarioSolicitanteId,DepartamentoId,CategoriaId,PrioridadId,Descripcion,FechaCreacion,EstadoId,TecnicoAsignadoId,PersonaBeneficiaria);
